-- Rollback-only, after candidate DDL. Do not expose actor IDs.
select set_config('rc33.qa.admin',(select user_id::text from registry_private.registration_administrators where active and revoked_at is null order by user_id limit 1),true);
select set_config('rc33.qa.finance',(select user_id::text from public.fs_staff_grants where role_code='cowl_finance_verifier' and revoked_at is null and granted_at<=now() and (expires_at is null or expires_at>now()) limit 1),true);
set local role authenticated;
do $$
#variable_conflict use_column
declare d jsonb;rev int; c uuid;w uuid;onl uuid;sup uuid;a uuid;g uuid;s uuid;req uuid;body jsonb;snap jsonb;it jsonb;b jsonb;omitted uuid;old_assignment uuid;method text;mid text:='Ministry of Lectors and Commentators';mas text:='Ministry of Altar Servers';m text;newid uuid;
begin
 perform set_config('request.jwt.claim.sub',current_setting('rc33.qa.admin'),true);
 c:=public.rc33_demo_open_cycle('RC33 Sample Parish A',2027);
 snap:=public.rc33_demo_snapshot('RC33 Sample Parish A',2027);
 select jsonb_agg(jsonb_build_object('assignment_id',x->>'id','proposal',case when x->>'first'='Maria' then 'renew' else 'no' end)) into body from jsonb_array_elements(snap->'roster') x where x->>'ministry'=mid;
 select (x->>'id')::uuid into old_assignment from jsonb_array_elements(snap->'roster') x where x->>'ministry'=mid and x->>'first'='Maria';
 select (x->>'id')::uuid into omitted from jsonb_array_elements(snap->'roster') x where x->>'ministry'=mid and x->>'first'='Jose';
 begin perform public.rc3_demo_submit('walk_in',2027,array[old_assignment]);raise exception 'LEGACY_BYPASS';exception when check_violation then null;end;
 d:=public.rc33_demo_open_draft(c,mid,'original','walk_in',null);
 rev:=(d->>'revision')::int;
 d:=public.rc33_demo_save_draft((d->>'id')::uuid,rev,jsonb_build_object('items',body,'method','OTC','letter','sample-mlc.pdf','confirmed',true,'zero',false));
 rev:=(d->>'revision')::int;
 begin perform public.rc33_demo_save_draft((d->>'id')::uuid,rev-1,d->'payload');raise exception 'STALE_DRAFT_ACCEPTED';exception when serialization_failure then null;end;
 w:=public.rc33_demo_submit_draft((d->>'id')::uuid,rev);
 if public.rc33_demo_submit_draft((d->>'id')::uuid,rev)<>w then raise exception 'RETRY_NOT_IDEMPOTENT';end if;
 if convert_from(substring(decode(public.rc33_demo_read_letter(w)->>'base64','base64') for 8),'UTF8')<>'%PDF-1.4' then raise exception 'BAD_SAMPLE_PDF';end if;
 perform public.rc33_demo_return_batch(w,1,'Correct fictional recommendation.');
 d:=public.rc33_demo_open_draft(c,mid,'original','walk_in',w);
 d:=public.rc33_demo_save_draft((d->>'id')::uuid,(d->>'revision')::int,jsonb_build_object('items',body,'method','OTC','letter','sample-mlc.pdf','confirmed',true,'zero',false));
 if public.rc33_demo_submit_draft((d->>'id')::uuid,(d->>'revision')::int)<>w then raise exception 'RETURNED_REFERENCE_CHANGED';end if;
 begin perform public.rc33_demo_complete_review(w,2);raise exception 'PREMATURE_REVIEW';exception when others then if sqlerrm='PREMATURE_REVIEW' then raise;end if;end;
 begin perform public.rc33_demo_review_letter(w,1);raise exception 'STALE_REVIEW_ACCEPTED';exception when others then if sqlerrm='STALE_REVIEW_ACCEPTED' then raise;end if;end;
 perform public.rc33_demo_review_letter(w,2);
 select x into b from jsonb_array_elements(public.rc33_demo_snapshot('RC33 Sample Parish A',2027)->'batches') x where x->>'id'=w::text;
 for it in select x from jsonb_array_elements(b->'items') x where x->>'decision'='pending' loop perform public.rc33_demo_review_item(w,(it->>'id')::uuid,'approved','',2);end loop;
 perform public.rc33_demo_complete_review(w,2);
 a:=public.rc33_demo_group_reviewed(c,array[w],'OTC');
 perform set_config('request.jwt.claim.sub',current_setting('rc33.qa.finance'),true);
 perform public.rc3_demo_authorize(a);
 select (x->>'payment_request_id')::uuid into req from jsonb_array_elements(public.rc3_demo_snapshot()->'applications') x where x->>'id'=a::text;
 begin perform public.fs_record_otc_payment(req,2500,now(),true);raise exception 'PARTIAL_ACCEPTED';exception when check_violation then if sqlerrm not like 'RC3 renewal requires full payment%' then raise;end if;end;
 perform public.rc3_demo_post_otc(req,5000,now(),true);
 perform set_config('request.jwt.claim.sub',current_setting('rc33.qa.admin'),true);
 if public.rc33_demo_open_cycle('RC33 Sample Parish A',2027)<>c then raise exception 'DUPLICATE_CYCLE';end if;
 snap:=public.rc33_demo_snapshot('RC33 Sample Parish A',2027);
 if not exists(select 1 from jsonb_array_elements(snap->'batches') x where x->>'id'=w::text and x->>'channel'='walk_in' and x->>'financial_status'='renewed' and (x->>'paid_centavos')::bigint=5000 and x->>'letter_name'='sample-mlc.pdf') then raise exception 'WALK_IN_NOT_SYNCHRONIZED';end if;
 begin perform public.rc33_demo_submit_batch(c,mid,'original','online_rehearsal','QR',body,'duplicate.pdf',true,false);raise exception 'DUPLICATE_ORIGINAL';exception when unique_violation then null;end;
 begin perform public.rc33_demo_submit_batch(c,mid,'supplemental','online_rehearsal','QR',jsonb_build_array(jsonb_build_object('assignment_id',old_assignment,'proposal','renew')),'duplicate.pdf',true,false);raise exception 'DUPLICATE_ASSIGNMENT';exception when unique_violation then null;end;
 select jsonb_agg(jsonb_build_object('assignment_id',x->>'id','proposal',case when x->>'first'='Maria' then 'renew' else 'no' end)) into body from jsonb_array_elements(snap->'roster') x where x->>'ministry'=mas;
 onl:=public.rc33_demo_submit_batch(c,mas,'original','online_rehearsal','QR',body,'sample-mas.pdf',true,false);
 perform public.rc33_demo_review_letter(onl,1);
 select x into b from jsonb_array_elements(public.rc33_demo_snapshot('RC33 Sample Parish A',2027)->'batches') x where x->>'id'=onl::text;
 for it in select x from jsonb_array_elements(b->'items') x where x->>'decision'='pending' loop perform public.rc33_demo_review_item(onl,(it->>'id')::uuid,'approved','',1);end loop;
 perform public.rc33_demo_complete_review(onl,1);
 sup:=public.rc33_demo_submit_batch(c,mid,'supplemental','online_rehearsal','QR',jsonb_build_array(jsonb_build_object('assignment_id',omitted,'proposal','renew'),jsonb_build_object('first_name','Beatriz','last_name','Salazar','proposal','new_member')),'sample-additions.pdf',true,false);
 perform public.rc33_demo_review_letter(sup,1);
 select x into b from jsonb_array_elements(public.rc33_demo_snapshot('RC33 Sample Parish A',2027)->'batches') x where x->>'id'=sup::text;
 for it in select x from jsonb_array_elements(b->'items') x where x->>'decision'='pending' loop perform public.rc33_demo_review_item(sup,(it->>'id')::uuid,'approved','',1);end loop;
 perform public.rc33_demo_complete_review(sup,1);
 begin perform public.rc33_demo_group_reviewed(c,array[w,sup],'QR');raise exception 'REUSE_GROUP';exception when others then if sqlerrm='REUSE_GROUP' then raise;end if;end;
 begin perform public.rc33_demo_group_reviewed(c,array[onl,sup],'QR');raise exception 'SUPPLEMENT_GROUPED';exception when others then if sqlerrm='SUPPLEMENT_GROUPED' then raise;end if;end;
 g:=public.rc33_demo_group_reviewed(c,array[onl],'QR');
 s:=public.rc33_demo_group_reviewed(c,array[sup],'QR');
 perform set_config('request.jwt.claim.sub',current_setting('rc33.qa.finance'),true);
 perform public.rc3_demo_authorize(g);
 perform public.rc3_demo_authorize(s);
 snap:=public.rc33_demo_snapshot('RC33 Sample Parish A',2027);
 if snap->'roster'<>'[]'::jsonb or exists(select 1 from jsonb_array_elements(snap->'batches') x where x->'items'<>'[]'::jsonb) then raise exception 'FINANCE_IDENTITY_LEAK';end if;
 if not exists(select 1 from jsonb_array_elements(snap->'batches') x where x->>'id'=sup::text and x->>'aggregate_id'=s::text and (x->>'due_centavos')::bigint=10000) then raise exception 'GROUP_AMOUNT_WRONG';end if;
 perform set_config('request.jwt.claim.sub',current_setting('rc33.qa.admin'),true);
 perform public.rc3_demo_prepare_qr(g);
 perform public.rc3_demo_prepare_qr(s);
 perform set_config('request.jwt.claim.sub',current_setting('rc33.qa.finance'),true);
 declare cl uuid;good uuid;bad uuid;begin
 select (x->>'payment_request_id')::uuid into req from jsonb_array_elements(public.rc3_demo_snapshot()->'applications') x where x->>'id'=g::text;
 select p.id into strict cl from public.fs_payment_claims p where p.payment_request_id=req;
 select b.id into strict good from public.fs_bank_credits b join public.fs_payment_claims p on p.receiving_account_id=b.receiving_account_id where p.id=cl and b.bank_external_reference=p.submitted_external_reference;
 select b.id into strict bad from public.fs_bank_credits b join public.fs_payment_claims p on p.receiving_account_id=b.receiving_account_id where p.id=cl and b.bank_external_reference=p.submitted_external_reference||'-MISMATCH';
 begin perform public.rc3_demo_post_qr(cl,bad);raise exception 'QR_MISMATCH_ACCEPTED';exception when others then if sqlerrm='QR_MISMATCH_ACCEPTED' then raise;end if;end;
 perform public.rc3_demo_post_qr(cl,good);
 select (x->>'payment_request_id')::uuid into req from jsonb_array_elements(public.rc3_demo_snapshot()->'applications') x where x->>'id'=s::text;
 select p.id into strict cl from public.fs_payment_claims p where p.payment_request_id=req;
 select b.id into strict good from public.fs_bank_credits b join public.fs_payment_claims p on p.receiving_account_id=b.receiving_account_id where p.id=cl and b.bank_external_reference=p.submitted_external_reference;
 perform public.rc3_demo_post_qr(cl,good);
 end;
 perform set_config('request.jwt.claim.sub',current_setting('rc33.qa.admin'),true);
 snap:=public.rc33_demo_snapshot('RC33 Sample Parish A',2027);
 if (select count(*) from jsonb_array_elements(snap->'roster') x where x->>'renewal_date' is not null)<>4 then raise exception 'WRONG_RENEWAL_COUNT';end if;
 if (select count(*) from jsonb_array_elements(snap->'batches') x where x->>'financial_status'='renewed')<>3 then raise exception 'WRONG_BATCH_PROGRESS';end if;
 if not exists(select 1 from jsonb_array_elements(snap->'batches') x where x->>'id'=w::text and (x->>'paid_centavos')::bigint=5000 and x->>'aggregate_id'=a::text) then raise exception 'ORIGINAL_CHANGED';end if;
end $$;
